// Python-compatible error types and uncaught-exception output emulation.

export class ScheduleValueError extends Error {
  constructor(message) {
    super(message);
    this.name = 'ScheduleValueError';
  }
}

// Reproduces the stderr output of the original PyInstaller executable when an
// exception escapes from schedule's Job.at() called by test4.py line 10.
// sourceLine is the line number inside schedule/__init__.py that raised.
export function fatalTraceback(err, sourceLine) {
  const lines = [
    'Traceback (most recent call last):',
    '  File "test4.py", line 10, in <module>',
    `  File "schedule/__init__.py", line ${sourceLine}, in at`,
    `schedule.ScheduleValueError: ${err.message}`,
    `[PYI-${process.pid}:ERROR] Failed to execute script 'test4' due to unhandled exception!`,
  ];
  process.stderr.write(lines.join('\n') + '\n');
  process.exit(1);
}

