// Minimal black-box reimplementation of the pieces of Python's `schedule`
// library exercised by test4.py: schedule.every().monday.at(timeStr).

import { ScheduleValueError } from './pyerrors.mjs';

export class Job {
  constructor(interval) {
    this.interval = interval;
    this.unit = null;      // 'weeks' once a weekday is selected
    this.startDay = null;  // e.g. 'monday'
    this.atTime = null;
    this.jobFunc = null;   // set by .do(), never called here
  }

  // schedule.every().monday
  get monday() {
    this.startDay = 'monday';
    this.unit = 'weeks';
    return this;
  }

  at(timeStr) {
    // start_day is set, so the daily time format rules apply.
    if (!/^[0-2]\d:[0-5]\d(:[0-5]\d)?$/.test(timeStr)) {
      // schedule/__init__.py, line 514
      throw new ScheduleValueError(
        'Invalid time format for a daily job (valid format is HH:MM(:SS)?)'
      );
    }
    const [hourStr] = timeStr.split(':');
    const hour = parseInt(hourStr, 10);
    if (hour < 0 || hour > 23) {
      // schedule/__init__.py, line 547 (the literal "{}" is a bug in the
      // original library and is reproduced verbatim)
      throw new ScheduleValueError(
        'Invalid number of hours ({} is not between 0 and 23)'
      );
    }
    this.atTime = timeStr;
    return this;
  }

  // Matches Python's Job.__repr__ for this configuration.
  toString() {
    return `Job(interval=${this.interval}, unit=${this.unit}, do=None, args=(), kwargs={})`;
  }
}

export function every() {
  return new Job(1);
}

