import { ArgumentParser } from './lib/argparse.mjs';
import { every } from './lib/schedule.mjs';
import { ScheduleValueError, fatalTraceback } from './lib/pyerrors.mjs';

const parser = new ArgumentParser();
parser.add_argument('--a', { type: 'str', required: true });
parser.add_argument('--b', { type: 'str', required: true });
parser.add_argument('--c', { type: 'str', required: true });
const args = parser.parse_args();

try {
  const job = every().monday.at(args.a); // 创建每周一特定时间作业
  console.log(String(job));
} catch (err) {
  if (err instanceof ScheduleValueError) {
    // Match the original executable's stderr traceback and exit code 1.
    fatalTraceback(err, err.message.startsWith('Invalid number of hours') ? 547 : 514);
  }
  throw err;
}

